/**
 * A preparation inventory, not a filing serializer or a legal-readiness score.
 * Keep personal answers out of this module and out of automatic worksheet exports.
 * BC sections are conditional: the corporation's home statute remains the CBCA.
 */
export type FederalBcPreparationField = {
  id: string;
  label: string;
  requirement: "required" | "conditional" | "decision" | "recommended";
  visibility: "public-filing" | "restricted" | "internal" | "mixed";
  appliesWhen?: string;
  detail: string;
  sourceIds: string[];
};

export type FederalBcPreparationItem = {
  id: string; title: string; detail: string; sourceIds: string[];
};

export type FederalBcPreparationPack = {
  title: string;
  reviewedOn: string;
  scope: string;
  privacyNote: string;
  sources: { id: string; label: string; url: string }[];
  sections: { id: string; title: string; summary: string; fields: FederalBcPreparationField[] }[];
  rules: FederalBcPreparationItem[];
  sequence: FederalBcPreparationItem[];
};

const field = (
  id: string,
  label: string,
  requirement: FederalBcPreparationField["requirement"],
  visibility: FederalBcPreparationField["visibility"],
  detail: string,
  sourceIds: string[],
  appliesWhen?: string,
): FederalBcPreparationField => ({ id, label, requirement, visibility, detail, sourceIds, ...(appliesWhen ? { appliesWhen } : {}) });

